/**
 * spacegear logo: concept B "Shift". A planet split along the dash, its two halves sliding apart.
 * Generated by the identity kit's tools from the same geometry as the masters in docs/brand/svg/; change
 * these paths only together with the masters.
 *
 * - Outlined shapes only: no font, no live text, so it renders identically everywhere and on the server.
 * - Colour follows CSS: every shape is filled with `currentColor` (default `text-flame`). Optional hooks:
 *   `.brand-symbol .half-top`, `.half-bottom`, `.brand-wordmark .glyph`, `.glyph-tm` (for example, the
 *   two-tone "twilight" colourway on dark grounds fills `.half-top` with the ink colour).
 * - Decorative: the SVG is `aria-hidden`. The caller names the link, and the name must contain the visible
 *   text, e.g. `<Link aria-label="spacegear home"><Brand /></Link>`.
 * - Static: no motion here. Motion work may animate `.half-top` / `.half-bottom` (they slide like the curtain)
 *   and must leave them at rest under `prefers-reduced-motion: reduce`.
 */

type BrandProps = {
  /** Show the symbol before the wordmark (default true). `false` gives the wordmark alone. */
  symbol?: boolean;
  /** Show the drawn ™ after the wordmark (default false: see docs/brand/guidelines.md, "The ™"). */
  tm?: boolean;
  /** Size and colour. The height sets the symbol height (24–32 px in the nav). */
  className?: string;
};

/** Height of every Brand viewBox; the x-height is 100 units, so the symbol is 2.26 x-heights tall. */
export const BRAND_HEIGHT = 226.0;

const VIEWS = {"lockup": [0, 1244.28], "lockupTm": [0, 1329.28], "word": [332.0, 912.28], "wordTm": [332.0, 997.28], "symbol": [0, 252.0]} as const;

/** Upper and lower half of the split planet, in lockup units. */
export const SYMBOL_PATHS = {"half-top": "M0 100A100 100 0 0 1 200 100L0 100Z", "half-bottom": "M252 126A100 100 0 0 1 52 126L252 126Z"} as const;

