const TM_PATH = "M1254.28 64L1284.28 64L1284.28 69.52L1254.28 69.52L1254.28 64ZM1266.28 64L1272.28 64L1272.28 96L1266.28 96L1266.28 64ZM1289.28 64L1295.28 64L1295.28 96L1289.28 96L1289.28 64ZM1323.28 64L1329.28 64L1329.28 96L1323.28 96L1323.28 64ZM1289.28 64L1296.88 64L1313.08 92.06L1305.48 92.06L1289.28 64ZM1321.68 64L1329.28 64L1313.08 92.06L1305.48 92.06L1321.68 64Z";

/** The 16-24 px cut of the symbol (16 px grid on a 256 canvas): wider cut and shift so it stays crisp. */
export const SYMBOL_SMALL_PATHS = {"half-top": "M0 112A96 96 0 0 1 192 112L0 112Z", "half-bottom": "M256 144A96 96 0 0 1 64 144L256 144Z"} as const;

export default function Brand({ symbol = true, tm = false, className = "block h-6 w-auto text-flame lg:h-7" }: BrandProps) {
  const [x, width] = VIEWS[symbol ? (tm ? "lockupTm" : "lockup") : tm ? "wordTm" : "word"];
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={`${x} 0 ${width} ${BRAND_HEIGHT}`}
      className={className}
      fill="currentColor"
      aria-hidden="true"
      focusable="false"
    >
      {symbol ? (
        <g className="brand-symbol">
          <path className="half-top" d={SYMBOL_PATHS["half-top"]} />
          <path className="half-bottom" d={SYMBOL_PATHS["half-bottom"]} />
        </g>
      ) : null}
      <g className="brand-wordmark">
        {WORD_GLYPHS.map(([id, d]) => (
          <path key={id} className={`glyph ${id}`} d={d} />
        ))}
      </g>
      {tm ? <path className="glyph-tm" d={TM_PATH} /> : null}
    </svg>
  );
}

/** The symbol alone (for the footer badge core, loaders, avatars). `small` = the 16-24 px cut. */
export function BrandSymbol({ small = false, className = "block h-6 w-auto text-flame" }: { small?: boolean; className?: string }) {
  const [x, width] = VIEWS.symbol;
  return small ? (
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 16 256 224" className={className} fill="currentColor" aria-hidden="true" focusable="false">
      <g className="brand-symbol">
        <path className="half-top" d={SYMBOL_SMALL_PATHS["half-top"]} />
        <path className="half-bottom" d={SYMBOL_SMALL_PATHS["half-bottom"]} />
      </g>
    </svg>
  ) : (
    <svg xmlns="http://www.w3.org/2000/svg" viewBox={`${x} 0 ${width} ${BRAND_HEIGHT}`} className={className} fill="currentColor" aria-hidden="true" focusable="false">
      <g className="brand-symbol">
        <path className="half-top" d={SYMBOL_PATHS["half-top"]} />
        <path className="half-bottom" d={SYMBOL_PATHS["half-bottom"]} />
      </g>
    </svg>
  );
}
